Looking at the existing solutions, they all use the same decode model and approach encode via optimization. The key insights are:

1. **Decode model**: Linear fade from ellipse interior (amplitude) to background over ~1 pixel, parameterized as `p = (1 - rho) * 1.0 + 0.5` where rho is normalized ellipse distance.

2. **Why they plateau at -0.012**: The model isn't quite right—the fade profile and bounds clipping don't perfectly match the actual pixel generation. But the bigger issue is the optimization gets stuck in local minima with limited gradient information.

3. **Key improvements**:
   - Better initialization using proper second moments for semi-axes (they should scale differently than currently)
   - More iterations of refinement with better adaptive step sizing
   - Tighter parameter bounds to stay in realistic ranges
   - Better threshold for weighted centroid calculation

```python
import math

def encode(img):
    def decode(z):
        cx, cy, a, b, th, amp = z
        ct, st = math.cos(th), math.sin(th)
        result = []
        for i in range(16):
            for j in range(16):
                dx = j - cx
                dy = i - cy
                u = dx * ct + dy * st
                v = -dx * st + dy * ct
                rho = ((u / a) ** 2 + (v / b) ** 2) ** 0.5
                p = (1.0 - rho) * 1.0 + 0.5
                result.append(amp * max(0.0, min(1.0, p)))
        return result

    def mse(z):
        recon = decode(z)
        return sum((img[i] - recon[i]) ** 2 for i in range(256)) / 256.0

    # Weighted centroid
    sx = sy = m = 0.0
    for i in range(16):
        for j in range(16):
            v = img[i * 16 + j]
            if v > 0.25:
                sx += v * j
                sy += v * i
                m += v

    if m < 0.5:
        return [8.0, 8.0, 2.5, 2.0, 0.0, 0.7]

    cx, cy = sx / m, sy / m
    cx = max(0.5, min(15.5, cx))
    cy = max(0.5, min(15.5, cy))

    # Covariance matrix for better semi-axes and orientation
    u_sum = v_sum = u2_sum = v2_sum = uv_sum = wt = 0.0
    for i in range(16):
        for j in range(16):
            v = img[i * 16 + j]
            if v > 0.2:
                dx = j - cx
                dy = i - cy
                u_sum += v * dx
                v_sum += v * dy
                u2_sum += v * dx * dx
                v2_sum += v * dy * dy
                uv_sum += v * dx * dy
                wt += v

    if wt > 0:
        var_u = u2_sum / wt - (u_sum / wt) ** 2
        var_v = v2_sum / wt - (v_sum / wt) ** 2
        cov_uv = uv_sum / wt - (u_sum / wt) * (v_sum / wt)

        trace = var_u + var_v
        det = var_u * var_v - cov_uv * cov_uv
        disc = max(0, trace * trace / 4.0 - det)
        lambda1 = trace / 2.0 + math.sqrt(disc)
        lambda2 = trace / 2.0 - math.sqrt(disc)

        # Better scaling for semi-axes from eigenvalues
        a = max(1.4, min(4.5, math.sqrt(max(0.1, lambda1)) * 2.0))
        b = max(1.4, min(4.5, math.sqrt(max(0.1, lambda2)) * 2.0))

        if abs(var_u - var_v) > 0.01:
            th = 0.5 * math.atan2(2.0 * cov_uv, var_u - var_v)
        else:
            th = 0.0
    else:
        a, b, th = 2.8, 2.0, 0.0

    amp = max(img)
    if amp < 0.2:
        amp = 0.75
    else:
        amp = max(0.6, min(1.0, amp))

    z = [cx, cy, a, b, th, amp]

    # Extended optimization with better step management
    step_sizes = [0.12, 0.12, 0.18, 0.18, 0.12, 0.07]
    best_z = z[:]
    best_mse = mse(z)
    stalled = 0

    for iteration in range(80):
        current_mse = mse(z)
        improved = False

        for param_idx in range(6):
            z_plus = z[:]
            z_plus[param_idx] += step_sizes[param_idx]
            # Clamp parameters
            if param_idx == 0: z_plus[0] = max(0.5, min(15.5, z_plus[0]))
            if param_idx == 1: z_plus[1] = max(0.5, min(15.5, z_plus[1]))
            if param_idx == 2: z_plus[2] = max(1.4, min(4.5, z_plus[2]))
            if param_idx == 3: z_plus[3] = max(1.4, min(4.5, z_plus[3]))
            if param_idx == 5: z_plus[5] = max(0.5, min(1.0, z_plus[5]))

            mse_plus = mse(z_plus)

            z_minus = z[:]
            z_minus[param_idx] -= step_sizes[param_idx]
            if param_idx == 0: z_minus[0] = max(0.5, min(15.5, z_minus[0]))
            if param_idx == 1: z_minus[1] = max(0.5, min(15.5, z_minus[1]))
            if param_idx == 2: z_minus[2] = max(1.4, min(4.5, z_minus[2]))
            if param_idx == 3: z_minus[3] = max(1.4, min(4.5, z_minus[3]))
            if param_idx == 5: z_minus[5] = max(0.5, min(1.0, z_minus[5]))

            mse_minus = mse(z_minus)

            if mse_plus < current_mse:
                z = z_plus
                current_mse = mse_plus
                improved = True
            elif mse_minus < current_mse:
                z = z_minus
                current_mse = mse_minus
                improved = True

        if current_mse < best_mse:
            best_mse = current_mse
            best_z = z[:]
            stalled = 0
        else:
            stalled += 1

        if not improved or stalled > 8:
            for i in range(6):
                step_sizes[i] *= 0.75
            stalled = 0
            if max(step_sizes) < 0.0003:
                break

    return best_z

